"""Ask a candidate `synaptory` binary which control plane it belongs to.

Two resolvers need this answer and used to spell it separately, which is how
one of them kept a defect the other had fixed. `gate_emitter._resolve_cli`
picks the binary a ceremony's telemetry is addressed to; `session_manager.
_resolve_cli_binary` picks the one the control-plane backend logs in with.
Both must refuse a binary stamped for the OTHER channel (#320), and both spawn
`<cli> status` to find out.

The property this module exists to protect is that **a probe that never
answered is not a probe that answered "no"**. Folding
`subprocess.TimeoutExpired` into the same falsey return as a mismatch makes a
loaded machine indistinguishable from a wrongly stamped binary, and the two
call for opposite responses: a mismatch means do not use this binary, a
timeout means we could not tell. #568 mechanism 3 caught it in `gate_emitter`
(events silently skipped under test load) and #396 caught the surviving copy
in `session_manager` (the control-plane backend falling back to local and
reporting the CLI as missing).

The verdicts are strings rather than booleans for exactly that reason: there
is no falsey value for a future edit to collapse them back into.

Pure logic + subprocess. Python 3.9 compatible: projected into every host
package.
"""
from __future__ import annotations

import os
import subprocess

#: Ceiling for one `<cli> status` probe.
#:
#: `status` reads a stamp off disk and prints a line, so this is generous for
#: the work. What it is not generous for is process spawn and scheduling on a
#: machine already running a few thousand tests, which is the constraint that
#: actually binds. The ceiling is HEADROOM; the fix is that a timeout stays a
#: distinct verdict, gets a bounded retry, and is reported.
PROBE_TIMEOUT_DEFAULT = 5.0

#: A probe verdict. `mismatch` and `unreadable` are answers; `timeout` is the
#: absence of one.
MATCH = "match"
MISMATCH = "mismatch"
UNREADABLE = "unreadable"  # it ran, and told us nothing useful
TIMEOUT = "timeout"  # it never answered


def probe_timeout() -> float:
    """The per-probe ceiling, overridable for pathologically loaded machines."""
    raw = os.environ.get("SYNAPTORY_CLI_PROBE_TIMEOUT", "").strip()
    if raw:
        try:
            value = float(raw)
        except ValueError:
            value = 0.0
        if value > 0:
            return value
    return PROBE_TIMEOUT_DEFAULT


def probe_channel_identity(candidate: str, local: bool, timeout: float) -> str:
    """Ask one candidate binary which control plane it belongs to."""
    try:
        probe = subprocess.run(
            [candidate, "status"],
            capture_output=True,
            text=True,
            check=False,
            timeout=timeout,
        )
    except subprocess.TimeoutExpired:
        return TIMEOUT
    except (OSError, subprocess.SubprocessError):
        return UNREADABLE
    identity = next(
        (
            line.split(":", 1)[1].strip()
            for line in probe.stdout.splitlines()
            if line.startswith("control_plane_url:")
        ),
        "",
    )
    # Explicit CI shims may not implement status at all.
    if not identity:
        return UNREADABLE
    try:
        from host_env import is_loopback_url
    except Exception:  # noqa: BLE001
        return UNREADABLE
    return MATCH if is_loopback_url(identity) == local else MISMATCH


class Unprobeable(Exception):
    """No answer from a candidate within the ceiling, twice.

    Carried as an exception rather than another falsey return so it cannot be
    silently re-collapsed into "did not match" by a future edit, which is the
    exact shape of the defect this replaces.
    """

    def __str__(self) -> str:  # the candidate path
        return str(self.args[0]) if self.args else "?"
